const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry Definitions
    const countries = ee.FeatureCollection("FAO/GAUL/2015/level0");
    const namibia = countries.filter(ee.Filter.eq('ADM0_NAME', 'Namibia'));
    const zimbabwe = countries.filter(ee.Filter.eq('ADM0_NAME', 'Zimbabwe'));

    // Check if geometries are valid
    if (namibia.size().getInfo() === 0 || zimbabwe.size().getInfo() === 0) {
      console.log("Error: Could not find country geometries.");
      console.log("C3"); // Calculation failure, as essential input is missing
      return;
    }
    const namibia_geom = namibia.geometry();
    const zimbabwe_geom = zimbabwe.geometry();

    // 2. Data Acquisition & Pre-processing
    const modis = ee.ImageCollection('MODIS/061/MOD13Q1')
      .select('NDVI'); // Select NDVI band

    // Scaling function for NDVI
    const scaleNDVI = function(image) {
      return image.divide(10000).copyProperties(image, ['system:time_start']);
    };

    // Target Period: Feb 21-28, 2019
    // MOD13Q1 images are 16-day composites. For Feb 21-28, 2019, the most relevant image
    // would typically be the one starting on Feb 17, 2019 (covering Feb 17 - Mar 4).
    const targetImageCollection = modis
      .filterDate('2019-02-17', '2019-03-05') // Filter for the 16-day period covering the target dates
      .map(scaleNDVI);

    const targetImageCount = targetImageCollection.size().getInfo();
    if (targetImageCount === 0) {
      console.log("No MODIS images found for the target period (Feb 2019).");
      console.log("C1");
      return;
    }
    const targetImage = targetImageCollection.first(); // Should be one image

    // Long-term average period: Feb 2003-2017
    const ltaCollection = modis
      .filter(ee.Filter.calendarRange(2003, 2017, 'year'))
      .filter(ee.Filter.calendarRange(2, 2, 'month')) // February
      .map(scaleNDVI);

    const ltaImageCount = ltaCollection.size().getInfo();
    if (ltaImageCount === 0) {
      console.log("No MODIS images found for the long-term average period (Feb 2003-2017).");
      console.log("C1");
      return;
    }
    const ltaImage = ltaCollection.mean(); // Mean of all February images from 2003-2017

    // Define the scale for reduceRegion (MODIS is 250m, use 1000m for faster processing)
    const scale = 1000;
    const reducer = ee.Reducer.mean();
    const pixelCountReducer = ee.Reducer.count();

    // Function to calculate mean NDVI and pixel count for a geometry
    const calculateStats = function(image, geometry, name) {
      const meanNDVI = image.reduceRegion({
        reducer: reducer,
        geometry: geometry,
        scale: scale,
        maxPixels: 1e9
      }).get('NDVI');

      const pixelCount = image.reduceRegion({
        reducer: pixelCountReducer,
        geometry: geometry,
        scale: scale,
        maxPixels: 1e9
      }).get('NDVI'); // Count pixels where NDVI is not masked

      return ee.Dictionary({
        'meanNDVI': ee.Number(meanNDVI),
        'pixelCount': ee.Number(pixelCount)
      });
    };

    // Calculate stats for Target Period (2019)
    const namibiaTargetStats = await calculateStats(targetImage, namibia_geom, 'Namibia').getInfo();
    const zimbabweTargetStats = await calculateStats(targetImage, zimbabwe_geom, 'Zimbabwe').getInfo();

    // Check for valid pixels for target period
    if (namibiaTargetStats.pixelCount === 0 || zimbabweTargetStats.pixelCount === 0) {
      console.log(`Target Period 2019: Namibia pixels: ${namibiaTargetStats.pixelCount}, Zimbabwe pixels: ${zimbabweTargetStats.pixelCount}`);
      console.log("C2");
      return;
    }

    // Calculate stats for Long-Term Average Period
    const namibiaLTAStats = await calculateStats(ltaImage, namibia_geom, 'Namibia').getInfo();
    const zimbabweLTAStats = await calculateStats(ltaImage, zimbabwe_geom, 'Zimbabwe').getInfo();

    // Check for valid pixels for LTA period
    if (namibiaLTAStats.pixelCount === 0 || zimbabweLTAStats.pixelCount === 0) {
      console.log(`LTA Period (2003-2017): Namibia pixels: ${namibiaLTAStats.pixelCount}, Zimbabwe pixels: ${zimbabweLTAStats.pixelCount}`);
      console.log("C2");
      return;
    }

    // Extract values
    const namibiaTargetNDVI = namibiaTargetStats.meanNDVI;
    const zimbabweTargetNDVI = zimbabweTargetStats.meanNDVI;
    const namibiaLTANDVI = namibiaLTAStats.meanNDVI;
    const zimbabweLTANDVI = zimbabweLTAStats.meanNDVI;

    // 3. Anomaly Calculation
    const namibiaAnomaly = namibiaTargetNDVI - namibiaLTANDVI;
    const zimbabweAnomaly = zimbabweTargetNDVI - zimbabweLTANDVI;

    // Check for C3 (NaN or null results)
    if (isNaN(namibiaAnomaly) || namibiaAnomaly === null ||
        isNaN(zimbabweAnomaly) || zimbabweAnomaly === null) {
      console.log("Error: Anomaly calculation resulted in NaN or null.");
      console.log("Namibia Target NDVI:", namibiaTargetNDVI, "LTA NDVI:", namibiaLTANDVI, "Anomaly:", namibiaAnomaly);
      console.log("Zimbabwe Target NDVI:", zimbabweTargetNDVI, "LTA NDVI:", zimbabweLTANDVI, "Anomaly:", zimbabweAnomaly);
      console.log("C3");
      return;
    }

    // 4. Comparison
    // "Worse" means more negative anomaly
    const isNamibiaWorse = namibiaAnomaly < zimbabweAnomaly;

    // Output results
    console.log(`Namibia 2019 Feb NDVI: ${namibiaTargetNDVI.toFixed(3)} (Pixels: ${namibiaTargetStats.pixelCount})`);
    console.log(`Zimbabwe 2019 Feb NDVI: ${zimbabweTargetNDVI.toFixed(3)} (Pixels: ${zimbabweTargetStats.pixelCount})`);
    console.log(`Namibia LTA Feb NDVI: ${namibiaLTANDVI.toFixed(3)} (Pixels: ${namibiaLTAStats.pixelCount})`);
    console.log(`Zimbabwe LTA Feb NDVI: ${zimbabweLTANDVI.toFixed(3)} (Pixels: ${zimbabweLTAStats.pixelCount})`);
    console.log(`Namibia Anomaly (2019 - LTA): ${namibiaAnomaly.toFixed(3)}`);
    console.log(`Zimbabwe Anomaly (2019 - LTA): ${zimbabweAnomaly.toFixed(3)}`);

    if (isNamibiaWorse) {
      console.log("A");
    } else {
      console.log("B");
    }

  } catch (e) {
    console.error("An error occurred: ", e);
    console.log("D"); // General error or syntax issue
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

